import time
from typing import Any


class AuthCache:
    def __init__(self, threshold: int = 500, default_timeout: float = 300):
        self.default_timeout = default_timeout
        self._cache: dict[str, tuple[float, Any]] = {}
        self.clear = self._cache.clear
        self._threshold = threshold

    def _prune(self):
        if len(self._cache) > self._threshold:
            now = time.time()
            toremove = []
            for idx, (key, (expires, _)) in enumerate(self._cache.items()):
                if (expires != 0 and expires <= now) or idx % 3 == 0:
                    toremove.append(key)
            for key in toremove:
                self._cache.pop(key, None)

    def _normalize_timeout(self, timeout: float | None) -> float:
        if timeout is None:
            timeout = self.default_timeout
        if timeout > 0:
            timeout = time.time() + timeout
        return timeout

    async def get(self, key: str) -> Any:
        try:
            expires, value = self._cache[key]
            if expires == 0 or expires > time.time():
                return value
        except KeyError:
            return None

    async def set(self, key: str, value: Any, timeout: float | None = None) -> bool:
        expires = self._normalize_timeout(timeout)
        self._prune()
        self._cache[key] = (expires, value)
        return True

    async def delete(self, key: str) -> bool:
        return self._cache.pop(key, None) is not None

    async def has(self, key: str) -> bool:
        try:
            expires, value = self._cache[key]
            return expires == 0 or expires > time.time()
        except KeyError:
            return False

from fastapi import HTTPException, status
from pydantic import UUID4

from mealie.core.security import hash_password
from mealie.core.security.providers.credentials_provider import CredentialsProvider
from mealie.db.models.users.users import AuthMethod
from mealie.routes._base import BaseUserController, controller
from mealie.routes._base.routers import UserAPIRouter
from mealie.routes.users._helpers import assert_user_change_allowed
from mealie.schema.response import ErrorResponse, SuccessResponse
from mealie.schema.user import ChangePassword, UserBase, UserOut
from mealie.schema.user.user import UserRatings, UserRatingSummary

user_router = UserAPIRouter(prefix="/users", tags=["Users: CRUD"])


@controller(user_router)
class UserController(BaseUserController):
    @user_router.get("/self", response_model=UserOut)
    def get_logged_in_user(self):
        return self.user

    @user_router.get("/self/ratings", response_model=UserRatings[UserRatingSummary])
    def get_logged_in_user_ratings(self):
        return UserRatings(ratings=self.repos.user_ratings.get_by_user(self.user.id))

    @user_router.get("/self/ratings/{recipe_id}", response_model=UserRatingSummary)
    def get_logged_in_user_rating_for_recipe(self, recipe_id: UUID4):
        user_rating = self.repos.user_ratings.get_by_user_and_recipe(self.user.id, recipe_id)
        if user_rating:
            return user_rating
        else:
            raise HTTPException(
                status.HTTP_404_NOT_FOUND,
                ErrorResponse.respond("User has not rated this recipe"),
            )

    @user_router.get("/self/favorites", response_model=UserRatings[UserRatingSummary])
    def get_logged_in_user_favorites(self):
        return UserRatings(ratings=self.repos.user_ratings.get_by_user(self.user.id, favorites_only=True))

    @user_router.put("/password")
    def update_password(self, password_change: ChangePassword):
        """Resets the User Password"""
        if self.user.auth_method == AuthMethod.LDAP:
            raise HTTPException(
                status.HTTP_400_BAD_REQUEST, ErrorResponse.respond(self.t("user.ldap-update-password-unavailable"))
            )
        if not CredentialsProvider.verify_password(password_change.current_password, self.user.password):
            raise HTTPException(
                status.HTTP_400_BAD_REQUEST, ErrorResponse.respond(self.t("user.invalid-current-password"))
            )

        self.user.password = hash_password(password_change.new_password)
        try:
            self.repos.users.update_password(self.user.id, self.user.password)
        except Exception as e:
            raise HTTPException(
                status.HTTP_400_BAD_REQUEST,
                ErrorResponse.respond("Failed to update password"),
            ) from e

        return SuccessResponse.respond(self.t("user.password-updated"))

    @user_router.put("/{item_id}")
    def update_user(self, item_id: UUID4, new_data: UserBase):
        assert_user_change_allowed(item_id, self.user, new_data)

        try:
            self.repos.users.update(item_id, new_data.model_dump())
        except Exception as e:
            raise HTTPException(
                status.HTTP_400_BAD_REQUEST,
                ErrorResponse.respond("Failed to update user"),
            ) from e

        return SuccessResponse.respond(self.t("user.user-updated"))

from fastapi import HTTPException, status
from pydantic import UUID4

from mealie.schema.response.responses import ErrorResponse
from mealie.schema.user.user import PrivateUser, UserBase

permission_attrs = ["can_invite", "can_manage", "can_manage_household", "can_organize", "admin"]


def _assert_non_admin_user_change_allowed(user_id: UUID4, current_user: PrivateUser, new_data: UserBase):
    if current_user.id != user_id:
        # User is trying to edit another user
        raise HTTPException(status.HTTP_403_FORBIDDEN, ErrorResponse.respond("User cannot edit other users"))

    if any(getattr(current_user, p) != getattr(new_data, p) for p in permission_attrs):
        # User is trying to change their own permissions
        raise HTTPException(
            status.HTTP_403_FORBIDDEN,
            ErrorResponse.respond("User cannot change their own permissions"),
        )

    if current_user.group != new_data.group:
        # prevent a regular user from changing their group
        raise HTTPException(
            status.HTTP_403_FORBIDDEN, ErrorResponse.respond("User doesn't have permission to change their group")
        )

    if current_user.household != new_data.household:
        # prevent a regular user from changing their household
        raise HTTPException(
            status.HTTP_403_FORBIDDEN,
            ErrorResponse.respond("User doesn't have permission to change their household"),
        )


def assert_user_change_allowed(user_id: UUID4, current_user: PrivateUser, new_data: UserBase):
    if not current_user.admin:
        _assert_non_admin_user_change_allowed(user_id, current_user, new_data)
        return

    if current_user.id != user_id:
        raise HTTPException(status.HTTP_403_FORBIDDEN, ErrorResponse.respond("Use the Admin API to update other users"))

    # Admin is trying to edit themselves
    if any(getattr(current_user, p) != getattr(new_data, p) for p in permission_attrs):
        # prevent an admin from excalating their own permissions
        raise HTTPException(
            status.HTTP_403_FORBIDDEN, ErrorResponse.respond("Admins can't change their own permissions")
        )

from datetime import timedelta

from fastapi import HTTPException, status

from mealie.core.security import create_access_token
from mealie.routes._base import BaseUserController, controller
from mealie.routes._base.routers import UserAPIRouter
from mealie.schema.user import (
    CreateToken,
    DeleteTokenResponse,
    LongLiveTokenCreateResponse,
    LongLiveTokenIn,
    LongLiveTokenInDB,
)

router = UserAPIRouter(prefix="/users", tags=["Users: Tokens"])


@controller(router)
class UserApiTokensController(BaseUserController):
    @router.post("/api-tokens", status_code=status.HTTP_201_CREATED, response_model=LongLiveTokenCreateResponse)
    def create_api_token(
        self,
        token_params: LongLiveTokenIn,
    ):
        """Create api_token in the Database"""

        token_data = {
            "long_token": True,
            "id": str(self.user.id),
            "name": token_params.name,
            "integration_id": token_params.integration_id,
        }

        five_years = timedelta(1825)
        token, _ = create_access_token(token_data, five_years)

        token_model = CreateToken(
            name=token_params.name,
            token=token,
            user_id=self.user.id,
        )

        new_token_in_db = self.repos.api_tokens.create(token_model)

        if new_token_in_db:
            return new_token_in_db

    @router.delete("/api-tokens/{token_id}", response_model=DeleteTokenResponse)
    def delete_api_token(self, token_id: int):
        """Delete api_token from the Database"""
        token: LongLiveTokenInDB = self.repos.api_tokens.get_one(token_id)

        if not token:
            raise HTTPException(status.HTTP_404_NOT_FOUND, f"Could not locate token with id '{token_id}' in database")

        # Ownership is by user id. Comparing emails happened to work since they're unique, but it
        # keys authorization on a mutable field and loads the user relationship to do it.
        if token.user_id == self.user.id:
            deleted_token = self.repos.api_tokens.delete(token_id)
            return DeleteTokenResponse(token_delete=deleted_token.name)
        else:
            raise HTTPException(status.HTTP_403_FORBIDDEN)

from functools import cached_property
from uuid import UUID

from fastapi import HTTPException, status
from pydantic import UUID4

from mealie.repos.all_repositories import get_repositories
from mealie.routes._base import BaseUserController, controller
from mealie.routes._base.routers import UserAPIRouter
from mealie.routes.users._helpers import assert_user_change_allowed
from mealie.schema.response.responses import ErrorResponse
from mealie.schema.user.user import UserRatingCreate, UserRatingOut, UserRatings, UserRatingUpdate

router = UserAPIRouter()


@controller(router)
class UserRatingsController(BaseUserController):
    @cached_property
    def group_recipes(self):
        return get_repositories(self.session, group_id=self.group_id, household_id=None).recipes

    def get_recipe_or_404(self, slug_or_id: str | UUID):
        """Fetches a recipe by slug or id, or raises a 404 error if not found."""
        if isinstance(slug_or_id, str):
            try:
                slug_or_id = UUID(slug_or_id)
            except ValueError:
                pass

        if isinstance(slug_or_id, UUID):
            recipe = self.group_recipes.get_one(slug_or_id, key="id")
        else:
            recipe = self.group_recipes.get_one(slug_or_id, key="slug")

        if not recipe:
            raise HTTPException(
                status.HTTP_404_NOT_FOUND,
                detail=ErrorResponse.respond(message="Not found."),
            )

        return recipe

    @router.get("/{id}/ratings", response_model=UserRatings[UserRatingOut])
    async def get_ratings(self, id: UUID4):
        """Get user's rated recipes"""
        assert_user_change_allowed(id, self.user, self.user)
        return UserRatings(ratings=self.repos.user_ratings.get_by_user(id))

    @router.get("/{id}/favorites", response_model=UserRatings[UserRatingOut])
    async def get_favorites(self, id: UUID4):
        """Get user's favorited recipes"""
        assert_user_change_allowed(id, self.user, self.user)
        return UserRatings(ratings=self.repos.user_ratings.get_by_user(id, favorites_only=True))

    @router.post("/{id}/ratings/{slug}")
    def set_rating(self, id: UUID4, slug: str, data: UserRatingUpdate):
        """Sets the user's rating for a recipe"""
        assert_user_change_allowed(id, self.user, self.user)

        recipe = self.get_recipe_or_404(slug)
        user_rating = self.repos.user_ratings.get_by_user_and_recipe(id, recipe.id)
        if not user_rating:
            self.repos.user_ratings.create(
                UserRatingCreate(
                    user_id=id,
                    recipe_id=recipe.id,
                    rating=data.rating,
                    is_favorite=data.is_favorite or False,
                )
            )
        else:
            if data.rating is not None:
                user_rating.rating = data.rating
            if data.is_favorite is not None:
                user_rating.is_favorite = data.is_favorite

            self.repos.user_ratings.update(user_rating.id, user_rating)

    @router.post("/{id}/favorites/{slug}")
    def add_favorite(self, id: UUID4, slug: str):
        """Adds a recipe to the user's favorites"""
        self.set_rating(id, slug, data=UserRatingUpdate(is_favorite=True))

    @router.delete("/{id}/favorites/{slug}")
    def remove_favorite(self, id: UUID4, slug: str):
        """Removes a recipe from the user's favorites"""
        self.set_rating(id, slug, data=UserRatingUpdate(is_favorite=False))

from typing import Annotated

from fastapi import APIRouter, Depends, Header
from sqlalchemy.orm.session import Session

from mealie.db.db_setup import generate_session
from mealie.schema.user.user_passwords import ForgotPassword, ResetPassword
from mealie.services.user_services.password_reset_service import PasswordResetService

router = APIRouter(prefix="")


@router.post("/forgot-password")
def forgot_password(
    email: ForgotPassword,
    session: Session = Depends(generate_session),
    accept_language: Annotated[str | None, Header()] = None,
):
    """Sends an email with a reset link to the user"""
    f_service = PasswordResetService(session)
    return f_service.send_reset_email(email.email, accept_language)


@router.post("/reset-password")
def reset_password(reset_password: ResetPassword, session: Session = Depends(generate_session)):
    """Resets the user password"""
    f_service = PasswordResetService(session)
    return f_service.reset_password(reset_password.token, reset_password.password)

from uuid import UUID

from fastapi import APIRouter, Depends
from slugify import slugify
from sqlalchemy.orm.session import Session

from mealie.db.db_setup import generate_session
from mealie.repos.all_repositories import get_repositories
from mealie.schema.response import ValidationResponse

router = APIRouter()


@router.get("/user/name", response_model=ValidationResponse)
def validate_user(name: str, session: Session = Depends(generate_session)):
    """Checks if a user with the given name exists"""
    db = get_repositories(session, group_id=None, household_id=None)
    existing_element = db.users.get_one(name, "username", any_case=True)
    return ValidationResponse(valid=existing_element is None)


@router.get("/user/email", response_model=ValidationResponse)
def validate_user_email(email: str, session: Session = Depends(generate_session)):
    """Checks if a user with the given name exists"""
    db = get_repositories(session, group_id=None, household_id=None)
    existing_element = db.users.get_one(email, "email", any_case=True)
    return ValidationResponse(valid=existing_element is None)


@router.get("/group", response_model=ValidationResponse)
def validate_group(name: str, session: Session = Depends(generate_session)):
    """Checks if a group with the given name exists"""
    db = get_repositories(session, group_id=None, household_id=None)
    existing_element = db.groups.get_by_name(name)
    return ValidationResponse(valid=existing_element is None)


@router.get("/household", response_model=ValidationResponse)
def validate_household(name: str, session: Session = Depends(generate_session)):
    """Checks if a household with the given name exists"""
    db = get_repositories(session, group_id=None, household_id=None)
    existing_element = db.households.get_by_name(name)
    return ValidationResponse(valid=existing_element is None)


@router.get("/recipe", response_model=ValidationResponse)
def validate_recipe(group_id: UUID, name: str, session: Session = Depends(generate_session)):
    """Checks if a recipe with the given slug exists"""
    db = get_repositories(session, group_id=None, household_id=None)
    slug = slugify(name)
    existing_element = db.recipes.get_by_slug(group_id, slug)
    return ValidationResponse(valid=existing_element is None)

