3	namespace App\Auth;
4	
5	use RuntimeException;
6	
7	/**
8	 * HS256 JWT compatible with mealie/core/security (PyJWT, ALGORITHM = "HS256").
9	 * compx574/hurl/run.sh calls encode() and secret() directly: keep both signatures.
10	 */
11	class Jwt
12	{
13	    public static function encode(array $claims, string $secret): string
14	    {
15	        $header = self::url(json_encode(['alg' => 'HS256', 'typ' => 'JWT']));
16	        $payload = self::url(json_encode($claims, JSON_UNESCAPED_SLASHES));
17	        $signature = self::url(hash_hmac('sha256', $header.'.'.$payload, $secret, true));
18	
19	        return $header.'.'.$payload.'.'.$signature;
20	    }
21	
22	    /** Returns the claims, or null when the signature, algorithm or exp is invalid. */
23	    public static function decode(string $token, string $secret): ?array
24	    {
25	        $parts = explode('.', $token);
26	        if (count($parts) !== 3) {
27	            return null;
28	        }
29	        [$header, $payload, $signature] = $parts;
30	
31	        $head = json_decode((string) self::urlDecode($header), true);
32	        if (! is_array($head) || ($head['alg'] ?? null) !== 'HS256') {
33	            return null;
34	        }
35	
36	        $expected = self::url(hash_hmac('sha256', $header.'.'.$payload, $secret, true));
37	        if (! hash_equals($expected, $signature)) {
38	            return null;
39	        }
40	
41	        $claims = json_decode((string) self::urlDecode($payload), true);
42	        if (! is_array($claims)) {
43	            return null;
44	        }
45	        if (isset($claims['exp']) && is_numeric($claims['exp']) && $claims['exp'] < time()) {
46	            return null;
47	        }
48	
49	        return $claims;
50	    }
51	
52	    /** Same rule as mealie/core/settings/settings.py determine_secrets(). */
53	    public static function secret(): string
54	    {
55	        $configured = config('mealie.secret');
56	        if (is_string($configured) && $configured !== '') {
57	            return $configured;
58	        }
59	
60	        if (! config('mealie.production')) {
61	            return 'shh-secret-test-key';
62	        }
63	
64	        $path = rtrim((string) config('mealie.data_dir'), '/').'/.secret';
65	        if (is_file($path)) {
66	            $secret = trim((string) file_get_contents($path));
67	            if ($secret !== '') {
68	                return $secret;
69	            }
70	        }
71	
72	        throw new RuntimeException('Mealie signing secret is not configured.');
73	    }
74	
75	    private static function url(string $value): string
76	    {
77	        return rtrim(strtr(base64_encode($value), '+/', '-_'), '=');
78	    }
79	
80	    private static function urlDecode(string $value): ?string
81	    {
82	        $decoded = base64_decode(strtr($value, '-_', '+/'), true);
83	
84	        return $decoded === false ? null : $decoded;
85	    }
86	}
