18	            400 => 'Bad Request',
19	            401 => 'Unauthorized',
20	            403 => 'Forbidden',
21	            404 => 'Not Found',
22	            405 => 'Method Not Allowed',
23	            409 => 'Conflict',
24	            default => 'Error',
25	        };
